def __init__(self, socksserver, selection_strategy, hops):
    self._logger = logging.getLogger(self.__class__.__name__)
    self.socksserver = socksserver
    self.selection_strategy = selection_strategy
    self.hops = hops

    self._udp_socket = None
    self.state = ConnectionState.BEFORE_METHOD_REQUEST
    self.buffer = ''

    self.destinations = {}

def dataReceived(self, data):
    self.buffer = self.buffer + data
    while len(self.buffer) > 0:
        # We are at the initial state, so we expect a handshake request.
        if self.state == ConnectionState.BEFORE_METHOD_REQUEST:
            if not self._try_handshake():
                break  # Not enough bytes so wait till we got more

        # We are connected so the
        elif self.state == ConnectionState.CONNECTED:
            if not self._try_request():
                break  # Not enough bytes so wait till we got more

        decoded = bdecode(data)
        if isinstance(decoded, dict) and decoded.get('y') in ['q', 'r', 'e']:
            return True
    except:
        pass
    return False

@staticmethod
def could_be_dispersy(data):
    return data[:TUNNEL_PREFIX_LENGHT] == TUNNEL_PREFIX and len(data) >= (23 + TUNNEL_PREFIX_LENGHT)

@staticmethod
def is_allowed(data):
    return (TunnelConversion.could_be_utp(data) or
            TunnelConversion.could_be_udp_tracker(data) or
            TunnelConversion.could_be_dht(data) or
            TunnelConversion.could_be_dispersy(data))
